    ('LJG', 'checkin', '安检流程与通道', '{"text": "承诺等待安检不超过15分钟；老、弱、病、残、孕、抱婴旅客、无人陪伴儿童、军人及消防救援人员设专用通道优先安检；随身行李过X光机，火种、刀具、超规液体不得随身携带"}'::jsonb, '二层安检区（国内安检口B01、B02）', '{"guide_chunk_ids": []}'::jsonb),
    ('LJG', 'checkin', '随身与托运行李限制', '{"text": "免费托运行李额与随身行李尺寸、重量由各航空公司自行公布，购票时核对；锂电池、充电宝禁止托运；未提取到行李可致电行李查询0888-5141026、0888-5141083、0888-5141078"}'::jsonb, NULL, '{"guide_chunk_ids": []}'::jsonb),
