    ('LJG', 'checkin', '144小时过境免签', '{"text": "2024年7月15日起丽江三义机场口岸适用144小时过境免签政策，54国公民可在云南停留不超过144小时；具体适用国别与办理要求以现场边检告知为准"}'::jsonb, '国际到达口岸联检区', '{"guide_chunk_ids": []}'::jsonb),
    ('LJG', 'facility', '母婴室', '{"text": "配婴儿打理台、洗手台及便于哺乳休息的座椅；无障碍卫生间同步完善"}'::jsonb, '候机楼出发与候机区域', '{"guide_chunk_ids": []}'::jsonb),
    ('LJG', 'facility', '无障碍设施', '{"text": "设无障碍通道、无障碍卫生间及低位服务设施，停车场预留无障碍车位；行动不便旅客可免费借用轮椅，残障旅客招援电话13988874305"}'::jsonb, '候机楼各层及停车场', '{"guide_chunk_ids": []}'::jsonb),
    ('LJG', 'facility', '饮水与充电', '{"text": "配饮水设备、候机座椅与移动电话充电装置；公共区域设公用电话"}'::jsonb, '候机隔离区、候机楼公共区域', '{"guide_chunk_ids": []}'::jsonb),
